// Assembles the section-navigation tree from the shared asset
// window.SEMICOLON_NAV (see _static/semicolon_nav_data.js, generated by
// scripts/gen_docs.py) into the placeholder emitted by the overridden
// _templates/sidebar-nav-bs.html. The markup mirrors pydata-sphinx-theme's
// generate_toctree_html output so the theme's own CSS styles it unchanged;
// only the current page's "current active" classes and open <details> are
// applied here, per page, from data-current.
(function () {
  "use strict";

  function build() {
    var root = document.getElementById("semicolon-nav");
    var mount = document.getElementById("semicolon-nav-tree");
    if (!root || !mount || !window.SEMICOLON_NAV) {
      return;
    }
    var dataRoot = root.getAttribute("data-root") || "";
    var current = root.getAttribute("data-current") || "";

    // The section-navigation tree belongs to the API Reference toctree only.
    // On other pages (Overview, landing) pydata's sidebar toctree was empty, so
    // leave the placeholder empty to match that behaviour.
    if (current.indexOf("api/") !== 0) {
      return;
    }

    function makeToggle() {
      var summary = document.createElement("summary");
      var span = document.createElement("span");
      span.className = "toctree-toggle";
      span.setAttribute("role", "presentation");
      var icon = document.createElement("i");
      icon.className = "fa-solid fa-chevron-down";
      span.appendChild(icon);
      summary.appendChild(span);
      return summary;
    }

    // Render one node. level is 1-based (toctree-l1, l2, ...). Returns
    // { li, onPath } where onPath is true if this node or a descendant is the
    // current page.
    function render(node, level) {
      var li = document.createElement("li");

      var a = document.createElement("a");
      a.className = "reference internal";
      a.href = dataRoot + node.u + ".html";
      a.textContent = node.t;
      li.appendChild(a);

      var isCurrent = node.u === current;
      var children = node.c || [];
      var onPath = isCurrent;

      if (children.length) {
        var details = document.createElement("details");
        details.appendChild(makeToggle());
        var ul = document.createElement("ul");
        for (var i = 0; i < children.length; i++) {
          var res = render(children[i], level + 1);
          ul.appendChild(res.li);
          if (res.onPath) {
            onPath = true;
          }
        }
        details.appendChild(ul);
        li.appendChild(details);

        // Top-level families are open by default (matches show_nav_level: 2);
        // deeper branches open only along the current page's path.
        if (level === 1 || onPath) {
          details.setAttribute("open", "");
        }

        li.className = "toctree-l" + level + " has-children";
      } else {
        li.className = "toctree-l" + level;
      }

      if (onPath) {
        li.classList.add("current");
        li.classList.add("active");
      }

      return { li: li, onPath: onPath };
    }

    var outer = document.createElement("ul");
    outer.className = "current nav bd-sidenav";
    for (var i = 0; i < window.SEMICOLON_NAV.length; i++) {
      outer.appendChild(render(window.SEMICOLON_NAV[i], 1).li);
    }
    mount.appendChild(outer);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", build);
  } else {
    build();
  }
})();
